Local Ltac band_lin :=
  repeat match goal with H : iclr ?a ?n |- _ => unfold iclr, AIMG_LO, AIMG_HI in H end.
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Local Ltac with_band H tac :=
